 "content": "def transform(grid):
    """Fill background gaps lying between same-color endpoints in a row or column."""
    h, w = len(grid), len(grid[0])
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    mark = next(v for row in grid for v in row if v != background)
    fill = 4
    cells = set()

    # Use original grid for endpoint tests; mark each straight gap between
    # consecutive marker cells when every intervening cell is background.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(positions, positions[1:]):
            if b > a + 1 and all(grid[r][c] == background for c in range(a + 1, b)):
                cells.update((r, c) for c in range(a + 1, b))

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(positions, positions[1:]):
            if b > a + 1 and all(grid[r][c] == background for r in range(a + 1, b)):
                cells.update((r, c) for r in range(a + 1, b))

    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = fill
    return out


if __name__ == '__main__':
